from author import *
c=C('算术运算、位操作与条件码')
L(c,'x86-64的加法与进位','x_flags',['按32位计算FFFFFFFFh+1。','低32位结果为0，CF=1，ZF=1。','CF跟踪无符号进位，OF跟踪有符号溢出。','标志位与目标寄存器分别保存状态。'],['先让EAX的三十二位全为一。把它按无符号整数解释，就是这个宽度的最大值。加一后，完整数学结果需要第三十三位，寄存器保留低三十二位零，进位写入CF。这样可以同时观察保存下来的位串，以及运算产生的进位信息。','这次CF为一，ZF也为一，因为保存的结果等于零。有符号解释则把原来的全一看成负一，负一加一得到零，所以这里的OF为零。读标志题时先写位宽，再选无符号或有符号解释，最后分别核对目标值与所需标志。'],[([1],1),([2],2)],['rax','eax'])
L(c,'A64的ADD与ADDS','a_flags',['ADD完成加法；ADDS还更新NZCV。','本例W0全1加1后为0，C=1，Z=1。','N/Z/C/V分别记录符号、零、进位与溢出。','需要条件信息时选择相应的置标志形式。'],['A六十四用指令形式表达是否更新条件标志。先让W零的三十二位全为一，再执行ADDS加一。结果同样保留低三十二位零，C记录进位，Z记录零结果。指令名末尾的S，在这个例子里提示它还会更新条件状态。','普通ADD用于取得和，ADDS则同时准备后续条件判断需要的信息。NZCV分别对应符号、零、进位与有符号溢出。连续分析多条指令时，顺便标出哪条最近更新了标志；后续条件指令就依据当前这组状态作出选择。'],[([1],1),([2],2)],['x0','w0'])
P(c,'两套架构的减法进位含义',['CMP形成比较用的条件信息，操作数保留。','x86-64比较1−2：CF=1表示发生借位。','A64比较1−2：C=0表示需要借位。','无符号小于分别使用JB与B.LO等对应条件。'],['比较通常通过相减形成条件信息，同时保留原操作数。这里把一减二作为同一个观察任务。x八六杠六十四的CF置一，表示无符号减法需要借位。A六十四在对应情况下让C为零，它的减法进位含义采用另一种约定。','因此，跨架构读代码时，先把条件转换回数值关系。无符号小于可以在x八六中用JB表达，在A六十四中用B点LO表达。大于关系也各自使用规定的组合条件。把原始标志解释清楚，再选择跳转名称，就能避免把两套同名或近似的字母直接套用。'],diagram='borrow')
L(c,'x86-64的逻辑右移与算术右移','x_shift',['SHR右侧移出，左侧补0。','SAR右侧移出，左侧复制原符号位。','32位80000000h右移1位分别得40000000h、C0000000h。','写EDX后RDX高32位清零；符号解释按32位进行。'],['先把三十二位的八零零零零零零零放进EAX，再逻辑右移一位。最高位补零，得到四零零零零零零零。逻辑移位适合把位串作为无符号数据处理。记录时先画出原来的最高位和移出的最低位，再写出保留的三十二位。','接着在EDX里准备同一位串，算术右移会复制原来的符号位，因此结果为C零零零零零零零。把这三十二位按补码解释，得到对应负数。写EDX同时清掉RDX高三十二位，所以完整六十四位显示与三十二位有符号解释要分别记录。'],[([1,2],2),([3,4],4)],['rax','rdx'])
L(c,'A64的LSR、ASR与位宽','a_shift',['W0准备32位80000000h。','LSR得到W1=40000000h。','ASR得到W2=C0000000h。','X1/X2高32位清零，按所选宽度解释结果。'],['A六十四把同样的逻辑右移写成LSR。先在W零准备三十二位数据，再把右移结果送入W一，来源W零继续保留。三操作数形式让来源和目标更容易分开观察，这个例子得到四零零零零零零零。','ASR把算术右移结果送入W二，得到C零零零零零零零。两条指令都按W寄存器的三十二位宽度工作。若后面需要一个真正符号扩展到六十四位的值，还要选择相应扩展操作。先确定本条指令的位宽，再分析高位的来源，整条数据流就清楚了。'],[([1,2],2),([3],3)],['x0','x1','x2'])
L(c,'x86-64的有符号除法','x_div',['IDIV RCX以RDX:RAX作为被除数。','CQO把RAX符号扩展到RDX:RAX。','−17÷5向零截断得商−3、余数−2。','商放RAX，余数放RDX。'],['这次把负十七放到RAX，再执行CQO，把符号扩展到RDX与RAX组成的被除数。六十四位IDIV使用这个双宽来源，所以高半部也是输入的一部分。接着让RCX保存除数五，准备完成一次有符号除法。','执行后，商为负三，余数为负二，分别放进RAX与RDX。它们满足被除数等于商乘除数再加余数，商采用向零截断。无符号DIV则按无符号方式准备高半部。除法题先把隐含输入和隐含输出都补到纸上，再开始计算。'],[([1,2,3],3),([4],4)],['rax','rdx','rcx'])
L(c,'A64的商与余数计算','a_div',['SDIV显式给出目标、被除数和除数。','−17÷5得到X2=−3。','MSUB计算X0−X2×X1，得到余数−2。','本例输入保持在X0/X1，结果放X2/X3。'],['A六十四的SDIV把目标和两个来源直接写在指令里。X零保存负十七，X一保存五，商进入X二，得到负三。这个写法方便把原始输入和计算结果放在不同位置，也方便后面继续使用被除数。','余数可以按被除数减去商乘除数来求。MSUB在这里计算X零减X二乘X一，把负二送进X三。完整核对式为负十七等于负三乘五再加负二。相同数学任务在两套架构中采用不同的寄存器组织，分析时先补全数据流即可。'],[([1,2,3],3),([4],4)],['x0','x1','x2','x3'])
P(c,'乘法、溢出与除零的架构规则',['低位乘积与完整双宽乘积是不同观察对象。','x86-64的MUL/IMUL形式需看隐含寄存器。','A64的MUL、UMULH、SMULH分别取得相应部分。','本课验证：x64整数除0触发异常；A64 UDIV除0得0。'],['乘法先问要保存多少位。两个六十四位数相乘，完整结果可能需要一百二十八位；只取低六十四位时，目标宽度已经给出截取范围。x八六的MUL和不同IMUL形式，以及A六十四的MUL、无符号高位乘法和有符号高位乘法，各自有明确的输入与结果规则。','执行异常也要按架构核对。本课的实际指令验证中，x八六整数除以零进入除法异常；A六十四的UDIV在除数为零时把商写成零。调用高级语言函数时还要遵守该语言本身的规则。阅读机器指令和阅读语言表达式，是两个有联系但各自有定义的层次。'],diagram='arithmetic')
Q(c,'比较1与2的进位状态',['x86-64执行CMP EAX,2，原EAX=1。','A64执行CMP W0,#2，原W0=1。','分别判断CF与C。','用各自架构的借位含义解释。'],'两套架构都比较一和二，相减时需要借位。x八六的CF是多少，A六十四的C又是多少？请把借位和各自标志的含义对应起来，接下来留四秒思考。','x八六的CF为一，表示发生借位；A六十四的C为零，表示本次减法需要借位。它们都能支持判断一小于二，只是标志编码采用不同约定。实际写分支时使用各自对应的无符号条件。',['x86-64：CF=1。','AArch64：C=0。','两者比较结果均为1<2。','跨架构先还原数值关系，再读条件。'])

c=C('比较、选择与循环')
L(c,'x86-64的有符号与无符号关系','x_compare',['同一64位全1可解释为最大无符号数或−1。','CMP后SETA按无符号大于写CL。','SETL按有符号小于写DL。','本例CL=1、DL=1，对应不同解释。'],['先把负一的六十四位补码放进RAX，再与一比较。如果按无符号解释，全一是这个宽度的最大整数，因此大于一。SETA把这个条件转成零或一，写入CL。比较的来源位串保持原样，条件指令依据当前标志给出布尔结果。','再用SETL按照有符号关系判断，负一小于一，所以DL也得到一。两个结果同时为一，对应的是两种数值解释。处理数组下标、长度或无符号字段时选择无符号条件，处理明确的有符号整数时选择有符号条件。先标类型，再读条件名称。'],[([1,2,3],3),([4],4)],['rax','rcx','rdx'])
L(c,'A64的HI、LO与LT、GE','a_compare',['HI/LO等条件用于无符号关系。','LT/GE等条件用于有符号关系。','CSET把当前条件变成0或1。','本例W1=1、W2=1。'],['A六十四同样让一份全一位串与一比较。CSET按HI条件把无符号大于关系写入W一，得到一。读这些条件时，把它们理解成规定好的数值关系，再根据需要回查NZCV的组合，这样更容易建立稳定的对应。','下一条按LT条件判断有符号小于关系，把一写入W二。全一按六十四位补码解释为负一，正好满足这个条件。与上一页对照，任务和结果相同，指令名字与标志组合属于各自架构。写跨平台代码时保持数据类型一致，再选对应条件。'],[([1,2,3],3),([4],4)],['x0','x1','x2'])
L(c,'x86-64的最大值分支','x_max',['先让RAX保留第一个候选。','CMP RDI,RSI准备有符号比较。','JGE成立直接保留，否则复制RSI。','输入3与9，最终返回9。'],['先把第一个参数复制到RAX，作为当前候选。接着比较RDI和RSI。如果第一个数大于等于第二个，JGE就直接到结束位置，候选保持原值。画控制流时可以把保留路径和更新路径分开，两条路径最后在返回处汇合。','本例第一个数为三，第二个为九，所以沿更新路径把RSI复制到RAX，最后返回九。相等时也会保留第一个候选。调试这类分支题，依次记录比较关系、实际路径和目标值，随后再检查是否选用了正确的有符号条件。'],[([1,2],2),([3,4],4)],['rax','rdi','rsi'])
L(c,'A64的条件选择CSEL','a_max',['CMP比较X0与X1。','CSEL按GE选择第一个或第二个来源。','数据选择由条件控制，执行位置顺序前进。','输入3与9，返回X0=9。'],['A六十四可以用条件选择完成同样任务。CMP先比较两个参数，CSEL的两个来源分别是X零和X一；GE成立时选前者，否则选后者，把结果送入目标X零。三个数据位置与一个条件一起描述本次选择。','输入三和九时，条件选择取得九，随后RET返回。这里改变的是进入目标的数据，指令位置仍顺序前进。条件跳转则会改变接下来执行哪条指令。读代码时把数据选择和控制流选择分别画出，两种实现都能完成最大值任务。'],[([1],1),([2],2)],['x0','x1'])
L(c,'x86-64的计数循环','x_loop',['ECX初始化为3，EAX清零。','每轮加2，再把计数减1。','JNZ回跳时读取DEC刚更新的零标志。','三轮后EAX=6、ECX=0。'],['先把EAX清零，再把循环次数三放进ECX。循环体让EAX加二，接着用DEC把计数减一。JNZ读取当前零标志，只要计数还没归零，就回到循环标签。初始化放在标签之前，回跳路径就会保留已有结果。','第一轮以后结果为二，第二轮为四，第三轮为六。最后一次DEC把ECX变成零，JNZ选择顺序离开。追踪循环时，把本轮数据更新和计数更新并排记录，再检查回跳读取的是哪条指令留下的条件状态。'],[([1,2],2),([3,4,5],5,3)],['rax','rcx'])
L(c,'A64的SUBS与B.NE','a_loop',['X0清零，X1准备3轮。','ADD更新结果，SUBS更新计数与标志。','B.NE在结果非零时回跳。','结束时X0=6、X1=0。'],['A六十四把结果放在X零，计数放在X一。每轮先加二，再用SUBS把计数减一。这里选择带S的形式，让减法同时更新条件标志，后面的B点NE就能根据是否为零决定回跳。','按三轮追踪，结果依次为二、四、六，计数依次为二、一、零。最后一次回跳条件结束，程序进入RET。遇到长度可能为零的任务，还要在第一次访问数据之前安排入口检查；下一章的数组例子会把这一步写出来。'],[([1,2],2),([3,4,5],5,3)],['x0','x1'])
Q(c,'找到循环读取的标志',['循环先更新累加结果。','然后递减循环计数。','最后按非零条件回跳。','判断最后一次递减之后的执行方向。'],'两套计数循环都在每轮末尾递减计数，并按非零条件回跳。计数从一减到零时，下一步走向哪里？请指出刚刚更新条件标志的指令，接下来留四秒思考。','计数归零以后，非零条件结束，执行按顺序离开循环。x八六例子由DEC更新标志，A六十四例子由SUBS更新标志。把最近一次条件写入与分支配对，就能解释最后一轮为什么结束。',['计数从1变0。','零条件成立，非零回跳结束。','x86-64读取DEC之后的标志。','A64读取SUBS之后的NZCV。'])

c=C('数组、字符串与数据布局')
L(c,'x86-64的uint32数组求和','x_sum',['RDI为起点，RSI为元素个数。','入口先检查长度，零长度直接返回0。','每项读取32位并零扩展，再参与64位累加。','3、5、7得到15，指针每轮前进4字节。'],['这个函数接收数组起点与元素个数，先清空累计结果，再检查长度。长度为零时直接到返回位置，第一次内存读取发生在确认至少有一个元素之后。这样，入口条件就与后面的访问范围连接起来。','每轮把一个三十二位元素读入ECX，再让它以零扩展后的六十四位值参加求和。指针加四，剩余数量减一，再决定是否继续。对于三、五、七，累加值依次为三、八、十五。核对结束位置时，用元素数量乘四字节计算总前进距离。'],[([1,2,3],2),([4,5,6,7,8],8,3)],['rax','rcx','rdi','rsi'])
L(c,'A64的数组加载与后变址','a_sum',['X0给起点，X1给长度，X2累计。','CBZ在长度为0时直接结束。','LDR W3,[X0],#4先取值，再更新指针。','把累计值送回X0作为整数返回结果。'],['A六十四先在X二准备累计值，并用CBZ检查长度。CBZ直接观察指定寄存器是否为零，适合表达这种入口条件。进入循环后，LDR读取当前X零指向的元素，再把X零向后移动四字节，这就是例子中的后变址。','W三接收数据时完成补零，X二累计，X一递减并提供回跳条件。三轮以后把十五从X二复制到X零，按照函数约定返回。追踪这种写法时，先记录本次实际读取的旧地址，再写指针的新值，访问顺序就清楚了。'],[([1,2],1),([3,4,5,6,7],7)],['x0','x1','x2','x3'])
L(c,'x86-64按零结束字节串计数','x_strlen',['RDI提供字节串起点。','检查[RDI+RAX]是否为0。','非零时计数加1并继续。','ABC加结束字节0，长度为3字节。'],['先把计数清零，再检查起点加计数的位置。字节为零时结束，非零时计数加一，再看下一个位置。这里的结束规则来自我们给定的数据格式，所以读内存前，要明确是哪一种字符串或缓冲区接口。','本例依次读到A、B、C，再读到零，最后返回三。它统计的是字节数。若内容采用UTF八编码，一个可见字符可能占多个字节，后续按字符处理还要遵守相应编码规则。当前例子先把逐字节检查和终止条件掌握清楚。'],[([1,2],2),([3,4,5],3,4)],['rax','rdi'])
L(c,'A64的字节串循环','a_strlen',['X2保存字节计数。','LDRB按起点和计数加载一个字节。','CBZ检查结束字节。','最终把计数3放入X0。'],['这次用X二计数，LDRB把起点加计数位置的字节送入W三。CBZ看到W三为零时离开，否则让计数加一再回到标签。字节加载、结束检查与计数更新在代码里逐步展开。','输入仍然是ABC和一个结束字节。完成以后X二为三，再把它复制到X零作为返回结果。对照上一页，可以逐项找出相同角色：起点、计数、当前字节和终止条件。换架构时先保持这张角色表，再映射到各自寄存器。'],[([1,2],2),([3,4,5,6],6)],['x0','x2','x3'])
L(c,'结构字段与固定偏移','x_struct',['教学布局：32位id在偏移0，8位标记在偏移4。','MOV EAX,[RDI]得到42。','MOVZX读取偏移4的字节，得到1。','布局来自明确字段宽度、顺序和对齐约定。'],['把结构体先画成连续字节：前四字节放编号，接下来一个字节放标记，其后可能有对齐填充。本例已经明确给出编号位于偏移零、标记位于偏移四。先读取四字节编号到EAX，再按字节读取标记并补零到EDX。','运行结果分别为四十二和一。真实C结构的布局还要依据目标平台、成员类型与对齐规则确认。阅读编译器输出时，可以先查清字段的实际偏移，再把方括号里的常量对应回字段名称；这比仅凭源代码排版估算位置更可靠。'],[([1],1),([2],2)],['rax','rdx','rdi'])
Q(c,'数组步长与零长度',['uint32_t数组每项4字节。','长度3时共读取3项。','长度0时先走入口结束路径。','分别判断指针变化与求和结果。'],'请比较长度为三和长度为零的数组求和。三项处理完后指针一共前进多少字节？零长度时结果是多少，第一次读取发生了吗？按入口检查和元素步长分别判断，接下来留四秒思考。','三项每项四字节，指针总共前进十二字节。零长度时入口检查直接结束，累计结果保持零，程序会跳过第一次元素读取。数组题把长度条件、每轮访问和结束位置连起来检查，就能覆盖这个边界。',['3项共前进12字节。','长度0返回累计初值0。','入口检查先于首次元素读取。','访问宽度与指针步长均按类型确定。'])
